export const EMBEDDED_MIGRATIONS: { name: string; sql: string }[] = [
  { name: "001_init.sql", sql: "-- Streetkey back end: first production schema (PostgreSQL 14+).\n-- db/schema.sql is the long-range design (PostGIS, vectors, contractors, lettings);\n-- this migration is what the running server uses today and grows by numbered migrations.\n\nCREATE EXTENSION IF NOT EXISTS pgcrypto;\nCREATE EXTENSION IF NOT EXISTS citext;\n\n-- ───────────── People & organisations ─────────────\nCREATE TABLE users (\n  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  email             citext UNIQUE NOT NULL,\n  password_hash     text NOT NULL,\n  display_name      text NOT NULL,\n  phone             text,\n  role              text NOT NULL DEFAULT 'member' CHECK (role IN ('member', 'admin')),\n  account_type      text NOT NULL DEFAULT 'buyer' CHECK (account_type IN ('buyer', 'owner', 'landlord', 'agent', 'developer', 'investor')),\n  email_verified_at timestamptz,\n  marketing_opt_in  boolean NOT NULL DEFAULT false,\n  created_at        timestamptz NOT NULL DEFAULT now(),\n  updated_at        timestamptz NOT NULL DEFAULT now(),\n  deleted_at        timestamptz\n);\n\nCREATE TABLE organisations (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name        text NOT NULL,\n  kind        text NOT NULL CHECK (kind IN ('agency', 'landlord', 'developer', 'contractor')),\n  verified    boolean NOT NULL DEFAULT false,      -- e.g. redress scheme / Companies House checked by an admin\n  redress_scheme text,                              -- The Property Ombudsman / Property Redress Scheme\n  created_at  timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE memberships (\n  organisation_id uuid NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  user_id         uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  role            text NOT NULL DEFAULT 'member' CHECK (role IN ('owner', 'admin', 'member')),\n  created_at      timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (organisation_id, user_id)\n);\n\n-- Session tokens are random; only their SHA-256 is stored.\nCREATE TABLE sessions (\n  token_hash  bytea PRIMARY KEY,\n  user_id     uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  last_seen_at timestamptz NOT NULL DEFAULT now(),\n  expires_at  timestamptz NOT NULL,\n  user_agent  text\n);\nCREATE INDEX ON sessions (user_id);\nCREATE INDEX ON sessions (expires_at);\n\n-- One-time links for email verification and password reset (hash only).\nCREATE TABLE email_tokens (\n  token_hash  bytea PRIMARY KEY,\n  user_id     uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  purpose     text NOT NULL CHECK (purpose IN ('verify', 'reset')),\n  expires_at  timestamptz NOT NULL,\n  used_at     timestamptz,\n  created_at  timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE consents (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id     uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  purpose     text NOT NULL CHECK (purpose IN ('terms', 'marketing', 'ai_image_processing', 'analytics')),\n  version     text NOT NULL DEFAULT '1',\n  granted_at  timestamptz NOT NULL DEFAULT now(),\n  withdrawn_at timestamptz\n);\nCREATE INDEX ON consents (user_id, purpose);\n\n-- ───────────── Listings ─────────────\n-- Full-text search document (declared immutable so it can back a generated column).\nCREATE FUNCTION listing_tsv(title text, town text, district text, ptype text, descr text, features text[]) RETURNS tsvector\n  LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$\n  SELECT setweight(to_tsvector('english'::regconfig, coalesce(town, '') || ' ' || coalesce(district, '')), 'A')\n      || setweight(to_tsvector('english'::regconfig, coalesce(title, '') || ' ' || coalesce(ptype, '')), 'B')\n      || setweight(to_tsvector('english'::regconfig, coalesce(array_to_string(features, ' '), '') || ' ' || coalesce(descr, '')), 'C')\n$$;\n\nCREATE TABLE listings (\n  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  ref              text UNIQUE NOT NULL,             -- short public id used in URLs, e.g. sk-7g4k2m\n  owner_user_id    uuid REFERENCES users(id) ON DELETE SET NULL,\n  organisation_id  uuid REFERENCES organisations(id) ON DELETE CASCADE,\n  source_kind      text NOT NULL CHECK (source_kind IN ('owner', 'landlord', 'agent-feed', 'agent')),\n  source_ref       text,                             -- agent's own reference (feeds)\n  channel          text NOT NULL CHECK (channel IN ('sale', 'rent')),\n  status           text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'pending', 'live', 'under_offer', 'sold', 'let', 'withdrawn', 'rejected')),\n  title            text,\n  address_line     text NOT NULL,                    -- never shown publicly in full for private sellers (street only)\n  town             text NOT NULL,\n  postcode         text NOT NULL,\n  district         text NOT NULL,\n  lat              double precision,\n  lng              double precision,\n  property_type    text NOT NULL,\n  tenure           text NOT NULL CHECK (tenure IN ('freehold', 'leasehold', 'share-of-freehold')),\n  lease_years      int,\n  beds             int NOT NULL CHECK (beds BETWEEN 0 AND 30),\n  baths            int NOT NULL CHECK (baths BETWEEN 0 AND 30),\n  floor_area       numeric NOT NULL CHECK (floor_area > 0),\n  era              text,\n  condition        text,\n  price            numeric NOT NULL CHECK (price > 0),\n  price_qualifier  text,\n  epc              text,\n  council_tax      text,\n  service_charge_annual numeric,\n  ground_rent_annual    numeric,\n  features         text[] NOT NULL DEFAULT '{}',\n  description      text,\n  material_info    jsonb NOT NULL DEFAULT '{}',      -- National Trading Standards material information (parts A–C)\n  ownership_declared boolean NOT NULL DEFAULT false,  -- seller confirmed they own it / have authority\n  ownership_verified boolean NOT NULL DEFAULT false,  -- checked by an admin (e.g. HM Land Registry title)\n  rejection_reason text,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  updated_at       timestamptz NOT NULL DEFAULT now(),\n  published_at     timestamptz,\n  search           tsvector GENERATED ALWAYS AS (listing_tsv(title, town, district, property_type, description, features)) STORED\n);\nCREATE UNIQUE INDEX listings_feed_ref ON listings (organisation_id, source_ref) WHERE source_ref IS NOT NULL;\nCREATE INDEX ON listings (status, channel, price);\nCREATE INDEX ON listings (district);\nCREATE INDEX ON listings (owner_user_id);\nCREATE INDEX listings_search ON listings USING gin (search);\n\nCREATE TABLE listing_photos (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  listing_id  uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,\n  storage_key text NOT NULL,\n  url         text NOT NULL,\n  content_type text NOT NULL,\n  bytes       int NOT NULL,\n  position    int NOT NULL DEFAULT 0,\n  alt         text,\n  created_at  timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX ON listing_photos (listing_id, position);\n\n-- ───────────── Buyers: saved homes, saved searches, enquiries ─────────────\nCREATE TABLE saved_listings (\n  user_id     uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  listing_key text NOT NULL,                         -- a Streetkey ref or a demo id\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (user_id, listing_key)\n);\n\nCREATE TABLE saved_searches (\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id         uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  query           text NOT NULL,\n  mode            text NOT NULL DEFAULT 'buy',\n  alert_frequency text NOT NULL DEFAULT 'daily' CHECK (alert_frequency IN ('instant', 'daily', 'weekly', 'off')),\n  last_alerted_at timestamptz,\n  created_at      timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (user_id, query, mode)\n);\n\nCREATE TABLE enquiries (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  listing_id    uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,\n  from_user_id  uuid REFERENCES users(id) ON DELETE SET NULL,\n  name          text NOT NULL,\n  email         citext NOT NULL,\n  phone         text,\n  kind          text NOT NULL CHECK (kind IN ('viewing', 'question', 'offer')),\n  preferred_slot text,\n  status        text NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'replied', 'closed')),\n  created_at    timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX ON enquiries (listing_id, created_at);\nCREATE INDEX ON enquiries (from_user_id);\n\nCREATE TABLE enquiry_messages (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  enquiry_id  uuid NOT NULL REFERENCES enquiries(id) ON DELETE CASCADE,\n  author      text NOT NULL CHECK (author IN ('enquirer', 'lister')),\n  author_user_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  body        text NOT NULL,\n  created_at  timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX ON enquiry_messages (enquiry_id, created_at);\n\n-- ───────────── Agent feeds ─────────────\nCREATE TABLE feed_keys (\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  organisation_id uuid NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  label           text NOT NULL,\n  prefix          text NOT NULL,                     -- first characters, shown in the UI\n  key_hash        bytea UNIQUE NOT NULL,\n  created_by      uuid REFERENCES users(id) ON DELETE SET NULL,\n  last_used_at    timestamptz,\n  revoked_at      timestamptz,\n  created_at      timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE feed_runs (\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  organisation_id uuid NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,\n  feed_key_id     uuid REFERENCES feed_keys(id) ON DELETE SET NULL,\n  format          text NOT NULL,\n  accepted        int NOT NULL,\n  withdrawn       int NOT NULL,\n  rejected        jsonb NOT NULL DEFAULT '[]',\n  created_at      timestamptz NOT NULL DEFAULT now()\n);\n\n-- ───────────── AI ─────────────\nCREATE TABLE ai_images (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id       uuid REFERENCES users(id) ON DELETE CASCADE,\n  room          text NOT NULL,\n  style         text NOT NULL,\n  brief         text,\n  prompt        text NOT NULL,\n  source_key    text,\n  result_key    text,\n  result_url    text,\n  model         text NOT NULL,\n  status        text NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'done', 'failed')),\n  error         text,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  finished_at   timestamptz\n);\nCREATE INDEX ON ai_images (user_id, created_at);\n\n-- ───────────── Engagement (consented, no personal data) ─────────────\nCREATE TABLE engagement_events (\n  id          bigserial PRIMARY KEY,\n  listing_id  uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,\n  session_id  text NOT NULL,                         -- random per browser session; not linked to a person\n  name        text NOT NULL CHECK (name IN ('listing_view', 'photo_open', 'floorplan_open', 'save', 'share', 'viewing_request', 'enquiry', 'ai_question', 'refurb_sim', 'design_style')),\n  occurred_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX ON engagement_events (listing_id, occurred_at);\n\n-- ───────────── Email log & audit ─────────────\nCREATE TABLE emails (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  to_address  citext NOT NULL,\n  template    text NOT NULL,\n  subject     text NOT NULL,\n  status      text NOT NULL CHECK (status IN ('sent', 'logged', 'failed')),\n  provider_id text,\n  error       text,\n  created_at  timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE audit_log (\n  id          bigserial PRIMARY KEY,\n  actor_user_id uuid,\n  action      text NOT NULL,\n  subject     text,\n  detail      jsonb,\n  ip          text,\n  at          timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX ON audit_log (at);\nCREATE INDEX ON audit_log (subject);\n" },
  { name: "002_ai_platform.sql", sql: "-- AI platform foundation: usage accounting, background jobs, distributed rate limits,\n-- and a key/value table for small runtime settings (e.g. the AI worker secret).\n\n-- Every OpenAI call: who/what it was for, model, tokens and latency (no prompts or outputs stored).\nCREATE TABLE ai_usage (\n  id            bigserial PRIMARY KEY,\n  user_id       uuid REFERENCES users(id) ON DELETE SET NULL,\n  purpose       text NOT NULL,                      -- e.g. assistant.chat, listing.describe, studio.room_image\n  model         text NOT NULL,\n  input_tokens  int NOT NULL DEFAULT 0,\n  output_tokens int NOT NULL DEFAULT 0,\n  images        int NOT NULL DEFAULT 0,\n  latency_ms    int NOT NULL DEFAULT 0,\n  ok            boolean NOT NULL DEFAULT true,\n  error_code    text,\n  at            timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX ON ai_usage (at);\nCREATE INDEX ON ai_usage (user_id, at);\nCREATE INDEX ON ai_usage (purpose, at);\n\n-- Long-running AI work (image editing, photo analysis, listing review) runs as jobs:\n-- the request enqueues, a worker (background function or in-process) processes, the browser polls.\nCREATE TABLE ai_jobs (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  kind          text NOT NULL,\n  user_id       uuid REFERENCES users(id) ON DELETE CASCADE,\n  subject       text,                               -- e.g. listing:sk-abc1234\n  status        text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'done', 'failed')),\n  input         jsonb NOT NULL DEFAULT '{}',\n  output        jsonb,\n  error         text,                               -- safe to show to the person\n  attempts      int NOT NULL DEFAULT 0,\n  progress      text,                               -- short human-readable progress note\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  started_at    timestamptz,\n  finished_at   timestamptz,\n  lease_until   timestamptz                         -- a running job whose lease expired can be retried\n);\nCREATE INDEX ON ai_jobs (status, created_at);\nCREATE INDEX ON ai_jobs (user_id, created_at);\nCREATE INDEX ON ai_jobs (subject);\n\n-- Fixed-window counters shared by every server instance (serverless-safe rate limiting).\nCREATE TABLE rate_limits (\n  key           text NOT NULL,\n  window_start  timestamptz NOT NULL,\n  count         int NOT NULL DEFAULT 0,\n  PRIMARY KEY (key, window_start)\n);\nCREATE INDEX ON rate_limits (window_start);\n\nCREATE TABLE app_settings (\n  key         text PRIMARY KEY,\n  value       text NOT NULL,\n  updated_at  timestamptz NOT NULL DEFAULT now()\n);\nINSERT INTO app_settings (key, value) VALUES ('ai_worker_secret', encode(gen_random_bytes(32), 'hex')) ON CONFLICT DO NOTHING;\n\n-- Short-lived cache for deterministic AI results (e.g. the same search phrase parsed twice).\nCREATE TABLE ai_cache (\n  key         text PRIMARY KEY,\n  value       jsonb NOT NULL,\n  expires_at  timestamptz NOT NULL\n);\nCREATE INDEX ON ai_cache (expires_at);\n\n-- Enquiries an automated screen judged to be spam or a scam are kept (for the record and appeals)\n-- but not emailed to the lister and shown under \"Filtered\" in their inbox.\nALTER TABLE enquiries ADD COLUMN IF NOT EXISTS filtered boolean NOT NULL DEFAULT false;\nALTER TABLE enquiries ADD COLUMN IF NOT EXISTS filter_reason text;\n" },
  { name: "004_search.sql", sql: "-- AI search: one embedding per live listing for semantic matching (\"similar homes\", AI relevance).\n-- Built from public listing facts and description only (never the private address).\n-- text_hash lets the embedding job skip listings whose text hasn't changed.\nCREATE TABLE listing_embeddings (\n  listing_id  uuid PRIMARY KEY REFERENCES listings(id) ON DELETE CASCADE,\n  model       text NOT NULL,\n  text_hash   text NOT NULL,\n  embedding   real[] NOT NULL,\n  updated_at  timestamptz NOT NULL DEFAULT now()\n);\n" },
  { name: "005_listing_ai.sql", sql: "-- AI help for people listing a property: per-photo analysis stored alongside each listing photo.\n-- Written by the 'listing.photos' background job (vision model, low detail) after photos are uploaded.\n-- Only labels and checks are stored here; no prompts and no model output beyond these fields.\nALTER TABLE listing_photos ADD COLUMN IF NOT EXISTS ai_room text;             -- e.g. 'kitchen', 'front exterior'\nALTER TABLE listing_photos ADD COLUMN IF NOT EXISTS ai_alt text;              -- suggested alt text (<= 120 chars)\nALTER TABLE listing_photos ADD COLUMN IF NOT EXISTS ai_quality jsonb;         -- { score: 1-10, issues: ['dark', 'blurry', ...] }\nALTER TABLE listing_photos ADD COLUMN IF NOT EXISTS ai_features text[];       -- features visible in the photo\nALTER TABLE listing_photos ADD COLUMN IF NOT EXISTS ai_flags text[];          -- 'people', 'personal-info', 'number-plate', ...\nALTER TABLE listing_photos ADD COLUMN IF NOT EXISTS ai_checked_at timestamptz; -- NULL = not analysed yet\nCREATE INDEX IF NOT EXISTS listing_photos_unchecked_idx ON listing_photos (listing_id) WHERE ai_checked_at IS NULL;\n" },
  { name: "006_trust.sql", sql: "-- AI trust & safety: an automated check of each submitted listing (content moderation of text\n-- and photos, code-computed scam/material-information signals, then an AI review) that helps\n-- admins prioritise the review queue. Reviews advise; people decide (AI never rejects).\nCREATE TABLE listing_ai_reviews (\n  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  listing_id         uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,\n  risk               text NOT NULL CHECK (risk IN ('low', 'medium', 'high')),\n  score              int NOT NULL CHECK (score BETWEEN 0 AND 100),     -- 0 = no concerns, 100 = almost certainly a problem\n  flags              jsonb NOT NULL DEFAULT '[]',                         -- [{type, severity, detail, evidence, source: rules|ai}]\n  signals            jsonb NOT NULL DEFAULT '{}',                         -- what the code checked (moderation, price vs area, duplicates…)\n  summary            text NOT NULL DEFAULT '',\n  suggested_reason   text,                                                -- polite, actionable wording for the lister if changes are needed\n  auto_approved      boolean NOT NULL DEFAULT false,\n  model              text,\n  triggered_by       text NOT NULL DEFAULT 'submitted' CHECK (triggered_by IN ('submitted', 'admin')),\n  listing_updated_at timestamptz,                                         -- the listing version reviewed (edits after this make it stale)\n  created_at         timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX listing_ai_reviews_latest ON listing_ai_reviews (listing_id, created_at DESC);\nCREATE INDEX listing_ai_reviews_auto ON listing_ai_reviews (created_at) WHERE auto_approved;\n" },
  { name: "007_inbox_ai.sql", sql: "-- AI for listers' inboxes: a triage of each enquiry (what they want, their buying position as\n-- stated in their own words, the questions they asked, how soon) so listers can prioritise.\n-- Written by the background job 'inbox.triage'; read only by the listing's lister.\nCREATE TABLE enquiry_ai (\n  enquiry_id      uuid PRIMARY KEY REFERENCES enquiries(id) ON DELETE CASCADE,\n  intent          text NOT NULL,                         -- book_viewing, ask_question, make_offer, ...\n  buyer_position  jsonb NOT NULL DEFAULT '{}',           -- only what the message states: chainFree, mortgageInPrinciple, cash, ...\n  questions       text[] NOT NULL DEFAULT '{}',          -- the enquirer's own questions, briefly\n  urgency         text NOT NULL DEFAULT 'unknown',       -- this_week, this_month, flexible, unknown\n  summary         text NOT NULL DEFAULT '',\n  sentiment       text NOT NULL DEFAULT 'neutral',       -- positive, neutral, negative\n  model           text,\n  messages_seen   int NOT NULL DEFAULT 0,                -- enquirer messages covered by this triage\n  created_at      timestamptz NOT NULL DEFAULT now(),\n  updated_at      timestamptz NOT NULL DEFAULT now()\n);\n\n-- The spam screen looks for the same text sent from one email address to many listings.\nCREATE INDEX IF NOT EXISTS enquiries_email_created_idx ON enquiries (email, created_at);\n" },
  { name: "008_enquiry_filter.sql", sql: "-- Enquiry spam/scam screening columns. These first shipped inside 002, after some databases had\n-- already applied 002, so they're (re)added here idempotently: every database ends up the same.\nALTER TABLE enquiries ADD COLUMN IF NOT EXISTS filtered boolean NOT NULL DEFAULT false;\nALTER TABLE enquiries ADD COLUMN IF NOT EXISTS filter_reason text;\n" },
  { name: "009_ai_actor.sql", sql: "-- Per-person AI token caps: who each AI call is charged to ('u:<user id>' or an anonymised visitor network).\nALTER TABLE ai_usage ADD COLUMN IF NOT EXISTS actor text;\nCREATE INDEX IF NOT EXISTS ai_usage_actor_at_idx ON ai_usage (actor, at) WHERE actor IS NOT NULL;\n\n-- Dashboard queries: saves per listing, and listings per organisation.\nCREATE INDEX IF NOT EXISTS saved_listings_key_idx ON saved_listings (listing_key);\nCREATE INDEX IF NOT EXISTS listings_org_idx ON listings (organisation_id) WHERE organisation_id IS NOT NULL;\nCREATE INDEX IF NOT EXISTS engagement_views_idx ON engagement_events (listing_id, occurred_at) WHERE name = 'listing_view';\n\n-- Background jobs remember who their AI usage is charged to.\nALTER TABLE ai_jobs ADD COLUMN IF NOT EXISTS actor text;\n" },
  { name: "010_saved_search_query.sql", sql: "-- Saved searches keep the filters the person saw (the validated reading, after removing chips and\n-- setting page filters), so alerts run exactly that search instead of re-reading the words with the\n-- built-in rules. NULL for searches saved before this change (alerts read their words as before).\nALTER TABLE saved_searches ADD COLUMN IF NOT EXISTS filters jsonb;\n" },
  { name: "011_trust_fixes.sql", sql: "-- Trust & safety fixes.\n-- 1. Edits to a submitted or live private listing are re-reviewed ('edited'), so changes made after approval\n--    can't skip the checks.\n-- 2. A review remembers a fingerprint of the content it checked (text, price, address, material information and\n--    photos), so \"changed since it was checked\" means the content changed, not just any update such as an approval.\nALTER TABLE listing_ai_reviews DROP CONSTRAINT IF EXISTS listing_ai_reviews_triggered_by_check;\nALTER TABLE listing_ai_reviews ADD CONSTRAINT listing_ai_reviews_triggered_by_check CHECK (triggered_by IN ('submitted', 'admin', 'edited'));\nALTER TABLE listing_ai_reviews ADD COLUMN IF NOT EXISTS content_hash text;\n-- Recently edited live listings (the admin's \"changed since approval\" list).\nCREATE INDEX IF NOT EXISTS listing_ai_reviews_edited ON listing_ai_reviews (created_at) WHERE triggered_by = 'edited';\n" },
  { name: "012_inbox_fixes.sql", sql: "-- Inbox fixes.\n--\n-- Which enquirer messages the spam/scam screen held back (never emailed to the lister). A\n-- conversation can be held from its first message, or from a follow-up the screen caught later;\n-- \"Not spam\" emails exactly the held messages, then clears the flag.\nALTER TABLE enquiry_messages ADD COLUMN IF NOT EXISTS held boolean NOT NULL DEFAULT false;\n-- Conversations already held back: until now only their opening message was kept from the lister\n-- (later messages were emailed anyway), so only that one is marked held and emailed on \"Not spam\".\nUPDATE enquiry_messages m SET held = true\n  FROM enquiries e\n WHERE e.id = m.enquiry_id AND e.filtered AND NOT m.held\n   AND m.id = (SELECT f.id FROM enquiry_messages f WHERE f.enquiry_id = e.id AND f.author = 'enquirer' ORDER BY f.created_at, f.id LIMIT 1);\n\n-- Stored triage from before the stricter checks (urgency, offers, questions and negated buying-position\n-- flags are now checked against the enquirer's words) may show chips the enquirer never earned. It is\n-- derived data: drop it, and each conversation is triaged again the next time its lister opens it.\nDELETE FROM enquiry_ai;\n" },
  { name: "013_listing_fixes.sql", sql: "-- Agent feeds: remember which feed key last supplied each listing, so an agency can send each branch's\n-- stock with its own key (keeping every upload under the hosting limit) without one branch's upload\n-- withdrawing another branch's listings. Listings imported before this change have no key and are\n-- treated as belonging to any of the agency's keys, as before.\nALTER TABLE listings ADD COLUMN IF NOT EXISTS feed_key_id uuid REFERENCES feed_keys(id) ON DELETE SET NULL;\nCREATE INDEX IF NOT EXISTS listings_feed_key_idx ON listings (feed_key_id) WHERE feed_key_id IS NOT NULL;\n" },
  { name: "014_studio_fixes.sql", sql: "-- Design studio: the site-wide daily cap on AI room redesigns (AI_DAILY_IMAGES_SITE) counts the\n-- designs started in the last 24 hours across all accounts, before each new one is queued.\nCREATE INDEX IF NOT EXISTS ai_images_created_idx ON ai_images (created_at);\n" },
  { name: "015_official_data.sql", sql: "-- Official open data kept locally so pages are fast and the public services aren't asked twice.\n--   sold_prices         HM Land Registry Price Paid Data (Open Government Licence v3.0), fetched per postcode on demand\n--   sold_price_fetches  which postcodes have been fetched, when, and how far back\n--   data_cache          everything else that is looked up (postcode locations, flood risk, energy certificates, house price index)\n\nCREATE TABLE IF NOT EXISTS sold_prices (\n  tx_id         text PRIMARY KEY,                 -- Land Registry transaction id\n  postcode      text NOT NULL,\n  paon          text,                             -- house name or number\n  saon          text,                             -- flat or unit\n  street        text,\n  locality      text,\n  town          text,\n  district      text,\n  price         integer NOT NULL,\n  sold_on       date NOT NULL,\n  property_type text NOT NULL,                    -- detached | semi-detached | terraced | flat | other\n  new_build     boolean NOT NULL DEFAULT false,\n  tenure        text,                             -- freehold | leasehold\n  standard      boolean NOT NULL DEFAULT true,    -- false: \"additional\" transactions (repossessions, buy-to-lets, transfers to companies)\n  fetched_at    timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS sold_prices_postcode_idx ON sold_prices (postcode, sold_on DESC);\n\nCREATE TABLE IF NOT EXISTS sold_price_fetches (\n  postcode   text PRIMARY KEY,\n  since      date NOT NULL,                       -- sales on or after this date are stored\n  rows       integer NOT NULL DEFAULT 0,\n  fetched_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS data_cache (\n  key        text PRIMARY KEY,                    -- e.g. flood:51.5906,-0.0185  epc:pc:E17 4PP  hpi:E09000031\n  value      jsonb NOT NULL,\n  fetched_at timestamptz NOT NULL DEFAULT now(),\n  expires_at timestamptz NOT NULL\n);\nCREATE INDEX IF NOT EXISTS data_cache_expires_idx ON data_cache (expires_at);\n" },
  { name: "016_listing_history.sql", sql: "-- Listing history, and the record that keeps saved-search alerts from repeating themselves.\n\n-- ───────────── Listing history ─────────────\n-- What happened to each listing on the market, so its page can show when it was first listed, every\n-- change to the asking price and how long it has been on the market. One row per event:\n--   listed        first went on the market\n--   price_change  the asking price changed (old_price → price)\n--   under_offer   marked under offer\n--   available     back on the market after being under offer\n--   sold | let    marked sold or let\n--   withdrawn     taken off the market\n--   relisted      back on the market after being withdrawn, sold or let\n-- price is the asking price (the monthly rent for a rental) at that moment. Nothing about who made a\n-- change is kept here (the audit trail has that), so the history can be shown publicly as it stands.\nCREATE TABLE IF NOT EXISTS listing_events (\n  id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  listing_id  uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,\n  kind        text NOT NULL CHECK (kind IN ('listed', 'price_change', 'under_offer', 'available', 'sold', 'let', 'withdrawn', 'relisted')),\n  price       numeric NOT NULL CHECK (price > 0),\n  old_price   numeric CHECK (old_price > 0),\n  at          timestamptz NOT NULL DEFAULT now(),\n  CHECK ((kind = 'price_change') = (old_price IS NOT NULL))\n);\nCREATE INDEX IF NOT EXISTS listing_events_listing_idx ON listing_events (listing_id, at, id);\n\n-- Listings that have already been on the market get their history from what is known about them.\n-- 1. First listed, on the day they were published. The price then is the \"from\" price of the first change\n--    the audit trail recorded after that day, or today's price when it recorded none.\nINSERT INTO listing_events (listing_id, kind, price, at)\nSELECT l.id, 'listed', coalesce(c.old_price, l.price), l.published_at\n  FROM listings l\n  LEFT JOIN LATERAL (\n    SELECT x.old_price\n      FROM (SELECT a.at, a.id,\n                   CASE WHEN a.detail->>'priceFrom' ~ '^[0-9]{1,12}(\\.[0-9]{1,4})?$' THEN (a.detail->>'priceFrom')::numeric END AS old_price,\n                   CASE WHEN a.detail->>'priceTo' ~ '^[0-9]{1,12}(\\.[0-9]{1,4})?$' THEN (a.detail->>'priceTo')::numeric END AS price\n              FROM audit_log a\n             WHERE a.subject = 'listing:' || l.ref AND a.action = 'listing.updated' AND a.at > l.published_at) x\n     WHERE x.old_price > 0 AND x.price > 0 AND x.old_price <> x.price\n     ORDER BY x.at, x.id LIMIT 1\n  ) c ON true\n WHERE l.published_at IS NOT NULL;\n\n-- 2. The price changes the audit trail recorded since then (edits by the lister and agency feed updates).\nINSERT INTO listing_events (listing_id, kind, price, old_price, at)\nSELECT x.listing_id, 'price_change', x.price, x.old_price, x.at\n  FROM (SELECT l.id AS listing_id, a.at, a.id,\n               CASE WHEN a.detail->>'priceFrom' ~ '^[0-9]{1,12}(\\.[0-9]{1,4})?$' THEN (a.detail->>'priceFrom')::numeric END AS old_price,\n               CASE WHEN a.detail->>'priceTo' ~ '^[0-9]{1,12}(\\.[0-9]{1,4})?$' THEN (a.detail->>'priceTo')::numeric END AS price\n          FROM listings l JOIN audit_log a ON a.subject = 'listing:' || l.ref\n         WHERE l.published_at IS NOT NULL AND a.action = 'listing.updated' AND a.at > l.published_at) x\n WHERE x.old_price > 0 AND x.price > 0 AND x.old_price <> x.price\n ORDER BY x.at, x.id;\n\n-- 3. Listings that are no longer simply for sale or to let: where they stand now, dated when the listing\n--    last changed (the exact day wasn't recorded before this table existed). A listing waiting for review\n--    after an edit counts as still on the market.\nINSERT INTO listing_events (listing_id, kind, price, at)\nSELECT l.id, CASE l.status WHEN 'under_offer' THEN 'under_offer' WHEN 'sold' THEN 'sold' WHEN 'let' THEN 'let' ELSE 'withdrawn' END,\n       l.price, greatest(l.updated_at, l.published_at)\n  FROM listings l\n WHERE l.published_at IS NOT NULL AND l.status IN ('under_offer', 'sold', 'let', 'withdrawn', 'draft', 'rejected');\n\n-- ───────────── Alerts: which listing has been emailed to which saved search ─────────────\n-- Both ways an alert goes out (the moment a listing goes live, and the hourly job) claim a row here\n-- before sending, so the same listing is never emailed twice to the same saved search.\nCREATE TABLE IF NOT EXISTS search_alert_sends (\n  saved_search_id uuid NOT NULL REFERENCES saved_searches(id) ON DELETE CASCADE,\n  listing_id      uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,\n  via             text NOT NULL CHECK (via IN ('instant', 'hourly')),\n  sent_at         timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (saved_search_id, listing_id)\n);\nCREATE INDEX IF NOT EXISTS search_alert_sends_listing_idx ON search_alert_sends (listing_id);\n-- Finding the searches that want an email \"as soon as they're listed\" must be quick: it runs each time a listing goes live.\nCREATE INDEX IF NOT EXISTS saved_searches_instant_idx ON saved_searches ((coalesce(last_alerted_at, created_at))) WHERE alert_frequency = 'instant';\n" },
];
